import os
from flask import Flask, render_template, request, jsonify
import requests
from dotenv import load_dotenv

load_dotenv()

app = Flask(__name__)

PAYPAL_CLIENT_ID = os.getenv('PAYPAL_CLIENT_ID')
PAYPAL_SECRET = os.getenv('PAYPAL_SECRET')
PAYPAL_API_BASE = ""

def get_paypal_access_token():
    url = f"{PAYPAL_API_BASE}/v1/oauth2/token"
    headers = {
        "Accept": "application/json",
        "Accept-Language": "en_US"
    }
    data = {
        "grant_type": "client_credentials"
    }
    response = requests.post(url, auth=(PAYPAL_CLIENT_ID, PAYPAL_SECRET), headers=headers, data=data)
    if response.status_code == 200:
        return response.json()['access_token']
    return None

@app.route('/')
def index():
    return render_template('index.html', client_id=PAYPAL_CLIENT_ID)

@app.route('/api/orders', methods=['POST'])
def create_order():
    access_token = get_paypal_access_token()
    if not access_token:
        return jsonify({"error": "Failed to get access token"}), 500

    data = request.get_json()
    amount = data.get('amount')

    url = f"{PAYPAL_API_BASE}/v2/checkout/orders"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {access_token}"
    }
    payload = {
        "intent": "CAPTURE",
        "purchase_units": [
            {
                "amount": {
                    "currency_code": "HUF",
                    "value": amount
                }
            }
        ]
    }

    response = requests.post(url, headers=headers, json=payload)
    return jsonify(response.json()), response.status_code

@app.route('/api/orders/<order_id>/capture', methods=['POST'])
def capture_order(order_id):
    access_token = get_paypal_access_token()
    if not access_token:
        return jsonify({"error": "Failed to get access token"}), 500

    url = f"{PAYPAL_API_BASE}/v2/checkout/orders/{order_id}/capture"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {access_token}"
    }

    response = requests.post(url, headers=headers)
    return jsonify(response.json()), response.status_code

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
