window.addEventListener('click', (e) => {
    const modal = document.getElementById('modal');
    if (e.target === modal) closeModal();
});
window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeModal();
});

document.addEventListener('DOMContentLoaded', () => {
    const container = document.querySelector('.cards-container');
    const cards = document.querySelectorAll('.card');
    if (!container || cards.length === 0) return;
    let startX = 0;
    let scrollStart = 0;
    let isDragging = false;
    let snapTimeout;
    let currentCardIndex = 0;
    let lastSnapTime = 0;
    function triggerHapticFeedback(intensity = 1) {
        if ('vibrate' in navigator) navigator.vibrate(intensity * 10);
    }
    function highlightCard(card) {
        cards.forEach(c => c.style.transform = 'scale(0.95)');
        card.style.transform = 'scale(1.02)';
        card.style.transition = 'transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
    }
    function updateBackgroundVideo(index) {
        const backgroundVideos = document.querySelectorAll('.background-video');
        backgroundVideos.forEach((video, i) => {
            if (i === index) {
                video.classList.add('active');
                video.play();
            } else {
                video.classList.remove('active');
            }
        });
    }
    updateBackgroundVideo(0);
    const allVideos = document.querySelectorAll('video');
    allVideos.forEach(video => video.play().catch(err => console.log("Video autoplay blocked", err)));
    let userInteracted = false;
    function startVideosOnInteraction() {
        if (!userInteracted) {
            userInteracted = true;
            allVideos.forEach(video => video.play().catch(err => console.log("Manual video play failed", err)));
        }
    }
    document.addEventListener('touchstart', startVideosOnInteraction, { once: true });
    document.addEventListener('click', startVideosOnInteraction, { once: true });
    container.addEventListener('touchstart', (e) => {
        startX = e.touches[0].clientX;
        scrollStart = container.scrollLeft;
        isDragging = true;
        clearTimeout(snapTimeout);
        triggerHapticFeedback(0.5);
        container.style.transition = 'none';
    }, { passive: true });
    container.addEventListener('touchmove', (e) => {
        if (!isDragging) return;
        const x = e.touches[0].clientX;
        const walk = startX - x;
        container.scrollLeft = scrollStart + walk;
    }, { passive: true });
    container.addEventListener('touchend', () => {
        isDragging = false;
        container.style.transition = 'scroll-behavior 0.3s ease';
        snapTimeout = setTimeout(snapToCard, 100);
    }, { passive: true });
    let isScrolling;
    container.addEventListener('scroll', () => {
        if (isDragging) return;
        window.clearTimeout(isScrolling);
        isScrolling = setTimeout(snapToCard, 100);
    }, { passive: true });
    function snapToCard() {
        const now = Date.now();
        if (now - lastSnapTime < 100) return;
        lastSnapTime = now;
        const containerRect = container.getBoundingClientRect();
        const containerCenter = containerRect.left + containerRect.width / 2;
        let closestCard = null;
        let closestDistance = Infinity;
        let newIndex = 0;
        cards.forEach((card, index) => {
            const cardRect = card.getBoundingClientRect();
            const cardCenter = cardRect.left + cardRect.width / 2;
            const distance = Math.abs(containerCenter - cardCenter);
            if (distance < closestDistance) {
                closestDistance = distance;
                closestCard = card;
                newIndex = index;
            }
        });
        if (closestCard) {
            const cardRect = closestCard.getBoundingClientRect();
            const containerRect = container.getBoundingClientRect();
            const scrollLeft = container.scrollLeft + cardRect.left - containerRect.left - (containerRect.width - cardRect.width) / 2;
            if (newIndex !== currentCardIndex) {
                triggerHapticFeedback(1);
                updateBackgroundVideo(newIndex);
                currentCardIndex = newIndex;
            }
            container.scrollTo({ left: scrollLeft, behavior: 'smooth' });
            highlightCard(closestCard);
        }
    }
    container.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowLeft') {
            if (currentCardIndex > 0) {
                currentCardIndex--;
                triggerHapticFeedback(1);
                updateBackgroundVideo(currentCardIndex);
                scrollToCard(currentCardIndex);
            }
        } else if (e.key === 'ArrowRight') {
            if (currentCardIndex < cards.length - 1) {
                currentCardIndex++;
                triggerHapticFeedback(1);
                updateBackgroundVideo(currentCardIndex);
                scrollToCard(currentCardIndex);
            }
        }
    });
    function scrollToCard(index) {
        const card = cards[index];
        const cardRect = card.getBoundingClientRect();
        const containerRect = container.getBoundingClientRect();
        const scrollLeft = container.scrollLeft + cardRect.left - containerRect.left - (containerRect.width - cardRect.width) / 2;
        highlightCard(card);
        container.scrollTo({ left: scrollLeft, behavior: 'smooth' });
    }
});

let currentDate = new Date();
let selectedDate = null;
let selectedTime = null;
let currentWeekStart = new Date();

function showCalendar() {
    document.querySelector('.header-container').classList.add('slide-out-up');
    document.querySelector('.cards-container').classList.add('slide-out-down');
    setTimeout(() => {
        document.getElementById('calendar-modal').classList.add('show');
        initializeDateSelection();
    }, 1000);
}

function hideCalendar() {
    document.getElementById('calendar-modal').classList.remove('show');
    showDateSelection();
    setTimeout(() => {
        document.querySelector('.header-container').classList.remove('slide-out-up');
        document.querySelector('.cards-container').classList.remove('slide-out-down');
    }, 1000);
}

function initializeDateSelection() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    document.getElementById('today-date').textContent = formatDate(today);
    document.getElementById('tomorrow-date').textContent = formatDate(tomorrow);
    showDateSelection();
}

function formatDate(date) {
    const options = { month: 'short', day: 'numeric' };
    return date.toLocaleDateString('hu-HU', options);
}

function formatDateFull(date) {
    const options = { year: 'numeric', month: 'long', day: 'numeric' };
    return date.toLocaleDateString('hu-HU', options);
}

function showDateSelection() {
    document.getElementById('date-selection').style.display = 'block';
    document.getElementById('calendar-view').style.display = 'none';
    document.getElementById('weekly-view').style.display = 'none';
    document.getElementById('time-selection').style.display = 'none';
}

function showWeeklyView() {
    document.getElementById('date-selection').style.display = 'none';
    document.getElementById('weekly-view').style.display = 'block';
    document.getElementById('calendar-view').style.display = 'none';
    document.getElementById('time-selection').style.display = 'none';
    generateWeeklyView();
}

function showCalendarView() {
    document.getElementById('date-selection').style.display = 'none';
    document.getElementById('calendar-view').style.display = 'block';
    document.getElementById('weekly-view').style.display = 'none';
    document.getElementById('time-selection').style.display = 'none';
    generateCalendar();
}

function showTimeSelection() {
    document.getElementById('date-selection').style.display = 'none';
    document.getElementById('calendar-view').style.display = 'none';
    document.getElementById('weekly-view').style.display = 'none';
    document.getElementById('time-selection').style.display = 'block';
    if (selectedDate) {
        document.getElementById('selected-date-display').textContent = formatDateFull(selectedDate);
    }
}

function selectQuickDate(type) {
    const today = new Date();
    if (type === 'today') {
        selectedDate = today;
    } else if (type === 'tomorrow') {
        selectedDate = new Date(today);
        selectedDate.setDate(today.getDate() + 1);
    }
    document.querySelectorAll('.quick-date-btn').forEach(btn => btn.classList.remove('selected'));
    event.target.closest('.quick-date-btn').classList.add('selected');
    setTimeout(() => {
        showTimeSelection();
    }, 300);
}

function openWeeklyView() {
    const today = new Date();
    const dayOfWeek = today.getDay();
    const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
    currentWeekStart = new Date(today);
    currentWeekStart.setDate(today.getDate() + mondayOffset);
    showWeeklyView();
}

function openCalendarView() {
    showCalendarView();
}

function generateWeeklyView() {
    const weekDays = ['Hétfő', 'Kedd', 'Szerda', 'Csütörtök', 'Péntek', 'Szombat', 'Vasárnap'];
    const timeSlots = ['16:00', '18:00', '20:00', '22:00'];
    const weekEnd = new Date(currentWeekStart);
    weekEnd.setDate(currentWeekStart.getDate() + 6);
    const startMonth = currentWeekStart.toLocaleDateString('hu-HU', { month: 'long' });
    const endMonth = weekEnd.toLocaleDateString('hu-HU', { month: 'long' });
    const year = currentWeekStart.getFullYear();
    let weekTitle;
    if (startMonth === endMonth) {
        weekTitle = `${year} ${startMonth} ${currentWeekStart.getDate()}-${weekEnd.getDate()}`;
    } else {
        weekTitle = `${year} ${startMonth} ${currentWeekStart.getDate()} - ${endMonth} ${weekEnd.getDate()}`;
    }
    document.getElementById('current-week').textContent = weekTitle;
    const weeklyDates = document.getElementById('weekly-dates');
    weeklyDates.innerHTML = '';
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    for (let i = 0; i < 7; i++) {
        const date = new Date(currentWeekStart);
        date.setDate(currentWeekStart.getDate() + i);
        const dayCard = document.createElement('div');
        dayCard.className = 'weekly-day-card';
        if (date < today) {
            dayCard.classList.add('disabled');
        }
        const dayHeader = document.createElement('div');
        dayHeader.className = 'weekly-day-header';
        dayHeader.textContent = weekDays[i];
        const dayDate = document.createElement('div');
        dayDate.className = 'weekly-day-date';
        dayDate.textContent = date.getDate();
        const slotsContainer = document.createElement('div');
        slotsContainer.className = 'weekly-day-slots';
        timeSlots.forEach(time => {
            const slot = document.createElement('button');
            slot.className = 'weekly-time-slot';
            slot.textContent = time;
            if (date >= today) {
                slot.onclick = () => selectWeeklyTimeSlot(date, time, slot);
            }
            slotsContainer.appendChild(slot);
        });
        dayCard.appendChild(dayHeader);
        dayCard.appendChild(dayDate);
        dayCard.appendChild(slotsContainer);
        weeklyDates.appendChild(dayCard);
    }
}

function selectWeeklyTimeSlot(date, time, element) {
    document.querySelectorAll('.weekly-time-slot').forEach(slot => slot.classList.remove('selected'));
    document.querySelectorAll('.weekly-day-card').forEach(card => card.classList.remove('selected'));
    element.classList.add('selected');
    element.closest('.weekly-day-card').classList.add('selected');
    selectedDate = date;
    selectedTime = time;
    setTimeout(() => {
        if (selectedDate && selectedTime) {
            hideCalendar();
            showAppointmentPaymentModal();
        }
    }, 500);
}

function previousWeek() {
    currentWeekStart.setDate(currentWeekStart.getDate() - 7);
    generateWeeklyView();
}

function nextWeek() {
    currentWeekStart.setDate(currentWeekStart.getDate() + 7);
    generateWeeklyView();
}

function backToQuickDates() {
    showDateSelection();
}

function backToDateSelection() {
    selectedTime = null;
    document.querySelectorAll('.time-slot').forEach(slot => slot.classList.remove('selected'));
    showDateSelection();
}

function generateCalendar() {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const monthNames = ['Január', 'Február', 'Március', 'Április', 'Május', 'Június', 'Július', 'Augusztus', 'Szeptember', 'Október', 'November', 'December'];
    document.getElementById('current-month').textContent = `${year} ${monthNames[month]}`;
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const startDate = new Date(firstDay);
    startDate.setDate(startDate.getDate() - (firstDay.getDay() === 0 ? 6 : firstDay.getDay() - 1));
    const datesGrid = document.getElementById('calendar-dates');
    datesGrid.innerHTML = '';
    for (let i = 0; i < 42; i++) {
        const date = new Date(startDate);
        date.setDate(startDate.getDate() + i);
        const dateCell = document.createElement('div');
        dateCell.className = 'date-cell';
        dateCell.textContent = date.getDate();
        dateCell.setAttribute('aria-label', `Válassz időpontot: ${formatDateFull(date)}`);
        if (date.getMonth() !== month) {
            dateCell.classList.add('other-month');
        }
        if (date < new Date().setHours(0,0,0,0)) {
            dateCell.style.opacity = '0.3';
            dateCell.style.cursor = 'not-allowed';
        } else {
            dateCell.onclick = () => selectCalendarDate(date, dateCell);
        }
        datesGrid.appendChild(dateCell);
    }
}

function selectCalendarDate(date, element) {
    document.querySelectorAll('.date-cell').forEach(cell => cell.classList.remove('selected'));
    element.classList.add('selected');
    selectedDate = date;
    setTimeout(() => {
        showTimeSelection();
    }, 300);
}

function selectTime(time) {
    selectedTime = time;
    document.querySelectorAll('.time-slot').forEach(slot => slot.classList.remove('selected'));
    event.target.classList.add('selected');
    setTimeout(() => {
        if (selectedDate && selectedTime) {
            hideCalendar();
